// static
bool StructTraits<::arc::mojom::PrivacyApplication::DataView, ::arc::mojom::PrivacyApplicationPtr>::Read(
    ::arc::mojom::PrivacyApplication::DataView input,
    ::arc::mojom::PrivacyApplicationPtr* output) {
  bool success = true;
  ::arc::mojom::PrivacyApplicationPtr result(::arc::mojom::PrivacyApplication::New());
  
      if (success && !input.ReadPackageName(&result->package_name))
        success = false;
      if (success)
        result->uid = input.uid();
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::arc::mojom::PrivacyItem::DataView, ::arc::mojom::PrivacyItemPtr>::Read(
    ::arc::mojom::PrivacyItem::DataView input,
    ::arc::mojom::PrivacyItemPtr* output) {
  bool success = true;
  ::arc::mojom::PrivacyItemPtr result(::arc::mojom::PrivacyItem::New());
  
      if (success && !input.ReadPermissionGroup(&result->permission_group))
        success = false;
      if (success && !input.ReadPrivacyApplication(&result->privacy_application))
        success = false;
  *output = std::move(result);
  return success;
}

